//! Catálogo de **slots** del juego: las claves lógicas que el juego dibuja
//! (`decor/tree`, `player/astronaut`, `items/apple`, `machines/…`, `tiles/water`).
//! El editor siembra su lista con esto para que NUNCA esté vacío y para que
//! puedas reskinear lo que el juego usa. Derivado de los catálogos reales
//! (`ha-shared/items.rs`, `machines.rs`) + las claves documentadas en
//! `assets/art/README.md`.
//!
//! **Cada slot lleva NOMBRE HUMANO** (`label`, en español). La clave es para el
//! código; el nombre es para vos: en el editor se lee "Puerta de madera", no
//! `door/wood`. Si agregás una clave nueva, ponele nombre — un slot sin nombre
//! es un slot que nadie va a saber qué es cuando le toque asignarle el pixel.
//!
//! "en un futuro que actualice": agregá la clave nueva acá y aparece en el editor.

/// Un slot de arte del juego.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SlotDef {
    /// Clave lógica = ruta (`"decor/tree"`). Es lo que el juego pide a ArtLibrary.
    pub key: &'static str,
    /// Nombre humano en español (`"Árbol"`). Es lo que se muestra en el editor.
    pub label: &'static str,
    /// Categoría para agrupar/filtrar en el editor.
    pub category: &'static str,
    /// Hint: suele ser animado (agua, npc). El usuario puede cambiarlo por slot.
    pub animated: bool,
}

const fn s(key: &'static str, label: &'static str, category: &'static str) -> SlotDef {
    SlotDef { key, label, category, animated: false }
}
const fn anim(key: &'static str, label: &'static str, category: &'static str) -> SlotDef {
    SlotDef { key, label, category, animated: true }
}

/// **Un estilo de interior completo**: el paño, su vano y su losa.
///
/// Las tres claves comparten sufijo porque el importador las emparejó **por
/// color** al recortarlas (`wall/int_verde_2` ↔ `doorway/int_verde_2` ↔
/// `floor/int_verde_2`). Viajar juntas en un struct, en vez de en tres listas
/// paralelas, es lo que hace imposible que se desalineen — y evita construir
/// `String`s en el bucle que pinta un chunk.
#[derive(Clone, Copy, Debug)]
pub struct EstiloInterior {
    /// El muro del cuarto, con **una pieza por orientación**: `edge_n` (el muro
    /// horizontal, tapa arriba y paño abajo), `edge_w`/`edge_e` (los verticales,
    /// vistos de canto), `edge_s` (el que da a la calle: se le ve la tapa),
    /// `corner_nw`/`corner_ne` (las esquinas en ángulo) y `end_w`/`end_e` (las
    /// jambas de un vano). **No hay cara de afuera**: `Room_Builder_*` es un kit
    /// de interior y la vereda la dibuja la fachada de Modern Exteriors.
    /// Quién pide cuál lo decide `world2d::cara_de_muro`.
    pub pared: &'static str,
    /// La pared CON el hueco ya dibujado (la hoja de arcos del pack). El mundo
    /// generado ya no la usa —en este kit un vano es un HUECO con sus jambas—,
    /// pero sigue publicada para colocarla a mano desde HA Studio.
    pub vano: &'static str,
    /// La losa que el artista puso en ese cuarto.
    pub piso: &'static str,
}

/// **Los estilos de interior del pack**, en el orden en que los dibuja la hoja.
///
/// Existe para que el cliente pueda decir "esta casa es del estilo 37" sin
/// escribir a mano ninguna de las claves: se derivan de [`INTERIOR_KEYS`],
/// que escribe `scripts/import-paredes-interiores.py`. Si el pack cambia y
/// aparecen o desaparecen estilos, esto acompaña solo.
///
/// El orden es el de la hoja y es estable entre corridas del importador: es lo
/// que hace que una casa conserve su empapelado de una partida a la otra sin
/// guardar nada.
pub fn interior_styles() -> &'static [EstiloInterior] {
    static CACHE: std::sync::OnceLock<Vec<EstiloInterior>> = std::sync::OnceLock::new();
    CACHE.get_or_init(|| {
        let busca = |pref: &str, sufijo: &str| -> Option<&'static str> {
            INTERIOR_KEYS
                .iter()
                .map(|&(k, _)| k)
                .find(|k| k.strip_prefix(pref) == Some(sufijo))
        };
        INTERIOR_KEYS
            .iter()
            .map(|&(k, _)| k)
            .filter_map(|pared| {
                let sufijo = pared.strip_prefix("wall/int_")?;
                Some(EstiloInterior {
                    pared,
                    vano: busca("doorway/int_", sufijo)?,
                    piso: busca("floor/int_", sufijo)?,
                })
            })
            .collect()
    })
}

/// Nombre humano de una categoría (encabezados del árbol del editor).
pub fn category_label(category: &str) -> &'static str {
    match category {
        "build" => "CONSTRUCCIÓN — piso, pared, puerta, ventana",
        "room" => "CONSTRUCCIÓN — cuartos y casas prefabricadas",
        "structure" => "CONSTRUCCIÓN — estructuras grandes",
        "interior" => "INTERIORES — paredes, vanos, pisos y remates de cuarto",
        "player" => "JUGADOR",
        "npc" => "PERSONAJES Y ANIMALES",
        "ship" => "NAVE",
        "decor" => "DECORADO DEL MUNDO — árboles, rocas, minerales",
        "prop" => "OBJETOS DE CALLE",
        "furniture" => "MUEBLES DE INTERIOR",
        "building" => "EDIFICIOS ENTEROS",
        "modular" => "EDIFICIO MODULAR — azotea, pisos, planta baja, tiendas",
        "vehicle" => "VEHÍCULOS",
        "nature" => "PLANTAS Y FLORES",
        "cultivo" => "HUERTA — tierra arada y cultivos por etapa",
        "props" => "COFRES Y CONTENEDORES",
        "tiles" => "SUELO DEL MUNDO — pasto, arena, agua, roca",
        "relieve" => "RELIEVE — acantilados y rampas",
        "agua" => "AGUA — decorado y pesca",
        "parcela" => "PATIO Y PARCELA — cercas, piletas, canchas",
        "ui" => "INTERFAZ / HUD",
        "backgrounds" => "FONDOS Y CIELO",
        "items" => "ÍTEMS DEL INVENTARIO",
        "machines" => "MÁQUINAS",
        _ => "OTROS",
    }
}

