/// **CONSTRUCCIÓN — piezas que el jugador coloca** (LimeZu `Room_Builder_32x32.png`).
///
/// Son las piezas de la pestaña CONSTRUIR de la mochila: el piso que pisás, la
/// pared que levantás, la puerta que cruzás. Autotile: el editor guarda poses
/// `center`/`edge_*`/`corner_*`/`inner_*` y el juego elige la variante por
/// vecinos (mismo pipeline que `tiles/water`). `door/*` además admite poses
/// `open`/`closed` (se abre sola por proximidad).
///
/// Sin arte asignado NO queda un hueco: cada pieza se dibuja con su color de
/// código (`Tile::color` / `walls::fallback_color`) — la puerta es un cuadrado
/// café, la pared de piedra un cuadrado gris. Asignás el pixel cuando querés.
const BUILD_ART_KEYS: &[(&str, &str)] = &[
    ("floor/wood", "Piso de madera"),
    ("floor/stone", "Piso de piedra"),
    // **El mismo juego de piezas en cada material** (`build_grid::EDGE_PIECES`):
    // pared, vano, puerta y ventana en madera, y las mismas cuatro en piedra. El
    // VANO es la pared con el hueco de la puerta —el marco—: el pack lo trae
    // dibujado para cada muro, y sin él no había forma de dejar un paso franco
    // entre dos ambientes.
    ("wall/wood", "Pared de madera"),
    ("doorway/wood", "Vano de madera (marco)"),
    ("door/wood", "Puerta de madera"),
    ("window/basic", "Ventana de madera"),
    ("wall/stone", "Pared de piedra"),
    ("doorway/stone", "Vano de piedra (marco)"),
    ("door/stone", "Puerta de piedra"),
    ("window/stone", "Ventana de piedra"),
    // **FACHADAS** — la cara de AFUERA, con el pixel de Modern Exteriors
    // (`scripts/import-fachadas.py`). Madera y piedra son el galpón y el tabique
    // de adentro; estos dos materiales son para la pared que da a la calle.
    //
    // Es el material entero el que cambia, no una pose: su cara de afuera (`back`)
    // es la elevación del pack y su cara de adentro (`front`) sigue siendo el paño
    // de Room Builder, porque una casa se ve casa desde la vereda y cuarto desde
    // adentro. Ver `walls::Cara` y biblia §5.
    ("wall/fachada_local", "Pared de local"),
    ("doorway/fachada_local", "Vano de local"),
    ("door/fachada_local", "Puerta de local"),
    ("window/fachada_local", "Vidriera de local"),
    ("wall/fachada_portal", "Pared de portal"),
    ("doorway/fachada_portal", "Vano de portal"),
    ("door/fachada_portal", "Puerta de portal"),
    ("window/fachada_portal", "Ventana de portal"),
    // Baranda: el borde del balcón o del hueco de escalera. Se dibuja a la
    // cintura (`build_grid::RAILING_RENDER_H`), no como una pared.
    ("railing/madera", "Baranda"),
    ("stairs/down", "Escalera para bajar"),
    ("stairs/up", "Escalera para subir"),
    // Vereda: el suelo urbano CAMINABLE (`Tile::Pavement`). Hasta que existió, la
    // obra civil pintaba las aceras con la roca del subsuelo, que es sólida — o
    // sea que las veredas de todas las ciudades eran muros.
    ("floor/vereda", "Vereda"),
    // **Las otras cinco veredas del pack.** Cada ciudad usa una entera —esta
    // baldosa y el `road/cordon_N` de su mismo número—, elegida por el centro
    // del asentamiento y nunca por celda. Ver `world2d::vereda_de_la_ciudad`.
    ("floor/vereda_tipo2", "Vereda de ciudad (tipo 2)"),
    ("floor/vereda_tipo3", "Vereda de ciudad (tipo 3)"),
    ("floor/vereda_tipo4", "Vereda de ciudad (tipo 4)"),
    ("floor/vereda_tipo5", "Vereda de ciudad (tipo 5)"),
    ("floor/vereda_tipo6", "Vereda de ciudad (tipo 6)"),
    ("floor/asfalto", "Asfalto (calle)"),
    // PINTURA DE LA CALZADA. Dos redes distintas: la línea sigue el EJE de la
    // calle (poses por conexión: `ns`, `ew`, `nse`…, las escribe
    // `scripts/import-calles.py`) y la senda cruza su ANCHO, justo antes del
    // cruce. Sin la segunda, una esquina no tenía por dónde cruzarse; y la
    // primera se cortaba en ninguna parte, así que las rayas se atravesaban en
    // medio de la intersección (ver `ha_shared::roads::Pintura`).
    ("road/linea", "Línea divisoria de la calzada"),
    ("road/senda_ns", "Senda peatonal (cruza una calle norte-sur)"),
    ("road/senda_ew", "Senda peatonal (cruza una calle este-oeste)"),
    // CORDÓN: el escalón por el que la vereda se levanta sobre la calle. Poses de
    // AUTOTILE (`edge_n`, `corner_ne`, `inner_sw`…) y sin `center`, porque una
    // calzada rodeada de calzada no lleva ninguno. Se dibuja sobre la celda de
    // asfalto —su cara cae del lado de la calle— y sólo contra vereda: una ruta
    // de campo con el pasto al borde no tiene cordón. Ver `spawn_chunk_cordon`.
    ("road/cordon", "Cordón de la vereda"),
    // **Una vereda por ciudad.** El pack dibujó seis familias enteras de acera y
    // el juego usaba una sola, así que todas las ciudades del mundo tenían la
    // misma. Cada ciudad toma una pareja completa —la baldosa
    // (`floor/vereda_tipoN`, en la hoja del suelo) y su cordón— elegida por el
    // centro del asentamiento, nunca por celda: un sorteo por celda pondría el
    // escalón de una familia sobre la baldosa de otra cada tres metros. Ver
    // `world2d::vereda_de_la_ciudad`.
    ("road/cordon_2", "Cordón de la vereda (tipo 2)"),
    ("road/cordon_3", "Cordón de la vereda (tipo 3)"),
    ("road/cordon_4", "Cordón de la vereda (tipo 4)"),
    ("road/cordon_5", "Cordón de la vereda (tipo 5)"),
    // SEMÁFORO: una cara por rumbo, no un sprite. Las arma
    // `scripts/import-semaforos.py` componiendo el poste del pack con la
    // calcomanía de lámparas (`*_Mod_*`), que sola no es un objeto. Cuál va en
    // cada esquina lo decide la geometría del cruce — ver
    // `ha_shared::worldgen::SEMAFOROS`.
    ("road/semaforo_frente", "Semáforo (de frente, prendido)"),
    ("road/semaforo_atras", "Semáforo (de espaldas)"),
    ("road/semaforo_izquierda", "Semáforo (de perfil, mira al oeste)"),
    ("road/semaforo_derecha", "Semáforo (de perfil, mira al este)"),
    // TAPAS (`build_grid::CEILING_PIECES`). El tumbado es la cara lisa que se ve
    // desde adentro del cuarto; los techos son de AFUERA y usan autotile
    // (`center`/`edge_*`/`corner_*`/`inner_*`), así que con recortar esas poses
    // una vez salen faldones, cumbreras y esquinas sin piezas sueltas.
    ("ceiling/madera", "Tumbado de madera"),
    ("ceiling/piedra", "Tumbado de piedra"),
    ("roof/teja", "Techo de teja (modular)"),
    ("roof/chapa", "Techo de chapa (modular)"),
    // SUBSUELO. Es lo único que se ve cuando estás abajo, así que tiene slot
    // propio y no reusa el de la roca: `tiles/subsuelo` es el macizo de tierra
    // que llena la pantalla y `floor/cueva` el suelo pisado de la galería y de
    // los sótanos que se excavan (el pack de interiores trae ambos).
    ("tiles/subsuelo", "Tierra del subsuelo (macizo)"),
    ("tiles/subsuelo_arcilla", "Subsuelo de arcilla (macizo)"),
    ("tiles/subsuelo_cristal", "Subsuelo de cristal (macizo)"),
    ("tiles/subsuelo_musgo", "Subsuelo de musgo (macizo)"),
    ("tiles/subsuelo_hierro", "Subsuelo de hierro (macizo)"),
    ("floor/cueva", "Suelo de cueva / sótano"),
];

/// **Las paredes de INTERIOR del pack, las 54, con su vano y su piso.**
///
/// Lo que `BUILD_ART_KEYS` es para el lado de afuera, esto es para el lado de
/// adentro. `wall/wood` y `wall/stone` alcanzaban mientras un cuarto fuera un
/// galpón; un cuarto se lee por su pared, y con dos estilos la cocina, el baño y
/// el dormitorio de toda la ciudad eran el mismo cuarto pintado del mismo
/// marrón. El kit entero estaba en el disco desde el primer día.
///
/// Cada estilo es un CUARTO del kit `Room_Builder_3d_walls`: su `wall/int_*` con
/// una pieza por orientación (`edge_n`, `edge_w`/`edge_e`, `edge_s`, las esquinas
/// en ángulo y las jambas de vano), su `doorway/int_*` y su `floor/int_*`.
///
/// El vano y la losa se emparejan **por color** con el paño, no por orden de hoja
/// — con una salvedad medida: la losa además tiene que SEPARARSE del paño en
/// brillo, o el cuarto entero sale de un solo tono y no se ve dónde termina el
/// piso y empieza la pared (ver el importador).
///
/// Después van las cinco familias de remate que el pack traía y nadie había
/// importado: zócalos, orlas, empalmes de piso, sendas y sombras al pie. Son
/// piezas de kit: se colocan desde el editor o las compone un importador,
/// **nunca se siembran sueltas** (regla 8 de biblia §2).
///
/// Entre los marcadores no se edita a mano: lo regenera
/// `scripts/import-paredes-interiores.py`.
