/// **EDIFICIO MODULAR** — el kit de `5_Floor_Modular_Buildings` de Modern
/// Exteriors, importado entero por `scripts/import-modulares.py`.
///
/// Son piezas de **9 celdas de frente**: ese es el módulo que dibujó el artista y
/// no se puede angostar sin cortar una ventana al medio. Un edificio se apila —
/// planta baja + N pisos + azotea— y se ensancha poniendo módulos al lado.
///
/// Cada slot trae sus variantes en el manifest (`edificio/piso_balcon#ladrillo`,
/// `#azul`, `#hormigon`), que son los tres temas que trae la hoja. El slot pelado
/// dibuja el primero, así que pedir `edificio/azotea` sin variante siempre da algo.
